/**
 * In-memory user store.
 *
 * The store is intentionally trivial — this is an evaluation app, not
 * production. The `demo`/`pass` credential pair is what the verifier signs
 * in with.
 */

export type UserRecord = {
  username: string;
  password: string;
};

export const USERS: readonly UserRecord[] = [
  { username: "demo", password: "pass" },
  { username: "admin", password: "admin" },
];

export function findUser(
  username: string,
  password: string,
): UserRecord | undefined {
  return USERS.find(
    (u) => u.username === username && u.password === password,
  );
}

export function findUserByUsername(
  username: string,
): UserRecord | undefined {
  return USERS.find((u) => u.username === username);
}

import { readFileSync } from "node:fs";
import {
  createSessionCookie,
  isValidSessionId,
  signSessionId,
} from "rwsdk/auth";

/**
 * The signed cookie value carries the username as the unsigned session id.
 *
 * Format: base64("<username>:<hex-hmac-sha256>")
 *
 * Because the signature uses HMAC-SHA256 with the secret read from
 * `/home/user/session_secret.txt`, any tampering of the signature portion
 * invalidates the cookie.
 */

const SESSION_COOKIE_NAME = "session";
const SESSION_SECRET_PATH = "/home/user/session_secret.txt";

let cachedSecret: string | undefined;

/** Read the signing secret from disk. Cached after the first read. */
function getSessionSecret(): string {
  if (cachedSecret !== undefined) {
    return cachedSecret;
  }
  const secret = readFileSync(SESSION_SECRET_PATH, "utf8").trim();
  if (!secret) {
    throw new Error(
      `Session secret at ${SESSION_SECRET_PATH} is empty. Cannot sign sessions.`,
    );
  }
  cachedSecret = secret;
  return cachedSecret;
}

const encoder = new TextEncoder();

/** Build the cookie header value that establishes a session for `username`. */
export async function buildSessionSetCookie(username: string): Promise<string> {
  const secretKey = getSessionSecret();
  const unsignedSessionId = encoder.encode(username);
  const signature = await signSessionId({
    unsignedSessionId: String(unsignedSessionId),
    secretKey,
  });
  const packed = `${username}:${signature}`;
  const sessionId =
    typeof btoa === "function" ? btoa(packed) : Buffer.from(packed).toString("base64");
  return createSessionCookie({
    name: SESSION_COOKIE_NAME,
    sessionId,
  });
}

/** Build the cookie header value that clears the session cookie. */
export function buildClearSessionCookie(): string {
  return createSessionCookie({
    name: SESSION_COOKIE_NAME,
    sessionId: "",
    maxAge: 0,
  });
}

/**
 * Pull the `session` cookie value out of a request, or `null` if it is
 * missing / malformed.
 */
export function readSessionCookie(request: Request): string | null {
  const cookieHeader = request.headers.get("Cookie");
  if (!cookieHeader) return null;
  for (const part of cookieHeader.split(";")) {
    const trimmed = part.trim();
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const name = trimmed.slice(0, eq);
    const value = trimmed.slice(eq + 1);
    if (name === SESSION_COOKIE_NAME && value) {
      return value;
    }
  }
  return null;
}

/** The username embedded in a valid session cookie, or `null` if invalid. */
export async function verifySessionCookie(
  request: Request,
): Promise<string | null> {
  const cookieValue = readSessionCookie(request);
  if (!cookieValue) return null;

  let decoded: string;
  try {
    decoded =
      typeof atob === "function"
        ? atob(cookieValue)
        : Buffer.from(cookieValue, "base64").toString("utf8");
  } catch {
    return null;
  }

  const colon = decoded.indexOf(":");
  if (colon === -1) return null;
  const username = decoded.slice(0, colon);
  const signature = decoded.slice(colon + 1);
  if (!username || !signature) return null;

  const secretKey = getSessionSecret();
  const valid = await isValidSessionId({
    sessionId: `${btoa(`${username}:${signature}`)}`,
    secretKey,
  });
  if (!valid) return null;

  // Re-derive the signature for the username using the same encoder used
  // at sign time. Because `isValidSessionId` already returned true, we
  // know the signature matched — but we re-verify explicitly so the
  // function returns the username cleanly.
  const expectedSignature = await signSessionId({
    unsignedSessionId: username,
    secretKey,
  });
  if (expectedSignature !== signature) return null;

  return username;
}

